#define NULL 0
#define TARGET_PS2
#define NGLCLEAR_COLOR 1
#define NGLCLEAR_Z 2
#define NGLCLEAR_STENCIL 0
#define WORLD_MIN_Z 0.05f
#define WORLD_MAX_Z 1.0f
#define START_PROF_TIMER(x)
#define STOP_PROF_TIMER(x)

struct nglSortInfo;
struct matrix4x4 { float m[4][4]; };
extern matrix4x4 identity_matrix;
class stringx
{
public:
  stringx(const char *, int = -1);
  ~stringx();
};
class camera
{
public:
  virtual void frame_advance(float);
  void adjust_geometry_pipe(bool = false);
};
class game_camera : public camera {};
class entity
{
  char pad[0x1f0];
public:
  void set_hero_id(int id) { *(int *)((char *)this + 0x1f0) = id; }
  void updatelighting(float, int);
};
class conglomerate : public entity
{
public:
  entity *get_member(const stringx &);
};
class kellyslater_controller
{
  char pad0[0x0c];
  entity *owner;
  char pad10[0xe3c];
  conglomerate *board_model;
  char pad_e50[0xd0c];
  camera *wipeout_cam;
  camera *wipeout_cam2;
  char pad_1b64[0x14];
  game_camera *photo_cam;
public:
  entity *get_owner() { return owner; }
  conglomerate *GetBoardModel() { return board_model; }
  camera *get_wipeout_cam_ptr() { return wipeout_cam; }
  camera *get_wipeout_cam2_ptr() { return wipeout_cam2; }
  game_camera *get_photo_cam_ptr() { return photo_cam; }
  void SetPlayerCamera(game_camera *);
};
class world_dynamics_system
{
  char pad[0xf8];
  kellyslater_controller *controllers[2];
public:
  kellyslater_controller *get_ks_controller(int i) { return controllers[i]; }
  void render(camera *, int);
};
class hw_rasta
{
public:
  static hw_rasta *inst();
  int get_screen_width() const;
  int get_screen_height() const;
};
class geometry_manager
{
public:
  enum xform_t { XFORM_LOCAL_TO_WORLD };
  static geometry_manager *inst();
  void set_cop(float, float, float, float);
  void set_xform(xform_t, const matrix4x4 &);
};
class vr_billboard { public: static void flush(); };
class FEManager { public: void UpdateIGOScene(); };
extern FEManager frontendmanager;
class os_developer_options
{
public:
  enum flags_t { FLAG_SHOW_MOTIONBLUR };
  static os_developer_options *inst();
  bool is_flagged(flags_t);
};
extern world_dynamics_system *g_world_ptr;
extern void nglListBeginScene(nglSortInfo * = 0);
extern void nglListEndScene();
extern void nglSetClearFlags(unsigned int);
extern void WAVETEX_SetPlayer(int);
extern void WAVETEX_CheckClearShadows();
extern void UNDERWATER_EntitiesTrackCamera();
extern void UNDERWATER_CameraChecks(int);
extern void BLUR_Draw();

class game
{
public:
  enum SNAPSTATE { SNAPSTATE_NONE, SNAPSTATE_BEGIN, SNAPSTATE_TEXTURE_RENDER };
  bool is_user_cam_on;
  char pad01[0x0b];
  world_dynamics_system *the_world;
  char pad10[0x18];
  camera *current_view_camera;
  char pad2c[0x34];
  camera *snapshotPrevCam;
  char pad64[4];
  SNAPSTATE snapshotState;
  char pad6c[0x1c];
  game_camera *player_cam[2];
  char pad90[0x2c];
  int active_player;
  void set_current_camera(camera *);
  void draw_debug_labels();
  void render_level_onescreen();
};

void game::render_level_onescreen()
{

	nglListBeginScene();
	WAVETEX_SetPlayer(active_player);

#ifndef TARGET_GC
	// For the early frames of the snapshot, use a special camera.
	if (snapshotState == SNAPSTATE_TEXTURE_RENDER)
	{
		if (!is_user_cam_on &&
			current_view_camera != the_world->get_ks_controller(active_player)->get_wipeout_cam_ptr() &&
			current_view_camera != the_world->get_ks_controller(active_player)->get_wipeout_cam2_ptr())
		{
			// Save old camera.
			snapshotPrevCam = current_view_camera;

			// Use photo cam for taking pictures.
			the_world->get_ks_controller(active_player)->SetPlayerCamera(the_world->get_ks_controller(active_player)->get_photo_cam_ptr());
			player_cam[active_player]->frame_advance(0.1f);
			player_cam[active_player]->adjust_geometry_pipe();
		}
		else
			snapshotPrevCam = NULL;
	}
#endif

	set_current_camera(player_cam[active_player]);

	UNDERWATER_EntitiesTrackCamera();
	UNDERWATER_CameraChecks(active_player);

	entity *ent = g_world_ptr->get_ks_controller(active_player)->get_owner();
	ent->set_hero_id(active_player);
	ent->updatelighting(0.1,active_player);
	ent= ((conglomerate *)g_world_ptr->get_ks_controller(active_player)->GetBoardModel())->get_member("BOARD");
	ent->set_hero_id(active_player);
	ent->updatelighting(0.1,active_player);

	WAVETEX_CheckClearShadows();

	// Prepare render.
	nglListBeginScene();
		// This is so we can use child scenes without the screen clear happening
		// after they're drawn
	nglSetClearFlags(NGLCLEAR_COLOR | NGLCLEAR_Z | NGLCLEAR_STENCIL);

	// Render the level.
	geometry_manager::inst()->set_cop(hw_rasta::inst()->get_screen_width()*0.5f,hw_rasta::inst()->get_screen_height()*0.5f, WORLD_MIN_Z, WORLD_MAX_Z);
	geometry_manager::inst()->set_xform(geometry_manager::XFORM_LOCAL_TO_WORLD, identity_matrix);
	START_PROF_TIMER( proftimer_render_world );
	the_world->render(current_view_camera, active_player); // render the main 3d scene
	STOP_PROF_TIMER( proftimer_render_world );
	vr_billboard::flush();

	draw_debug_labels();
	frontendmanager.UpdateIGOScene();
	nglListEndScene();

	if (os_developer_options::inst()->is_flagged(os_developer_options::FLAG_SHOW_MOTIONBLUR))
	{
		BLUR_Draw();
	}
	nglListEndScene();
}
